import{_ as a,o,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-08-18","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-08-18","date":"2021-08-18T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["Ceph","分布式存储","代码审查","问题解决","项目管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-08-18.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-08-18.md","lastUpdated":1780460162000}'),t={name:"posts/2021/Ceph_Crimson_SeaStore_2021-08-18.md"};function r(d,e,c,s,n,h){return o(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>参与者</strong>: 会议由包括Sam, Sean, Kifu等多名研发人员参与。</li><li><strong>时间</strong>: 会议讨论了近期工作进展和遇到的问题。</li><li><strong>项目</strong>: 主要集中在Ceph存储系统的开发与测试。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>代码修改与测试</strong>:</p><ul><li>开发者讨论了启用<code>syllabus</code>和将警告视为错误的功能，以避免潜在的替代品替换。</li><li>另一位开发者对<code>allocate x10</code>的PR进行了修改，并尝试在<code>cat</code>组件中重现常见问题。</li></ul></li><li><p><strong>版本更新与问题重现</strong>:</p><ul><li>讨论了更新到<code>master</code>分支后的问题，特别是在<code>interruptible future</code>中。</li><li>确认了使用的是<code>release build</code>，并测试了包含最新补丁的<code>master</code>分支。</li></ul></li><li><p><strong>问题跟踪与解决</strong>:</p><ul><li>提到了创建跟踪票来记录和解决遇到的问题。</li><li>讨论了重现<code>cache is dirty</code>问题的方法，该问题虽不总是发生，但发生频率较高。</li></ul></li><li><p><strong>代码审查与项目进展</strong>:</p><ul><li>Sam分享了对多个PR的审查工作，特别是关于<code>sway hounds</code>和<code>lba tree</code>的进展。</li><li>Sean提到了对<code>extent placement pr</code>的修改，以及对多设备支持的调整。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>使用包含最新补丁的<code>release build</code>进行测试。</li><li>继续跟踪和重现<code>cache is dirty</code>问题，并尝试找到稳定的重现方法。</li><li>完成对<code>sway hounds</code>和<code>lba tree</code>的审查，并推进相关项目的开发。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li>持续测试和验证<code>release build</code>中的问题，并确保所有警告被正确处理。</li><li>跟踪和解决<code>cache is dirty</code>问题，并更新跟踪票。</li><li>完成对<code>sway hounds</code>和<code>lba tree</code>的审查，并推进相关项目的开发。</li><li>对<code>extent placement pr</code>进行进一步的修改和测试。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>Kifu宣布将在团队的最后一周，团队成员对他的离开表示了感谢和祝福。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议涵盖了技术问题和项目进展，强调了持续测试、问题跟踪和代码审查的重要性。团队成员对Kifu的离开表示了遗憾和祝福。</p>',13)])])}const _=a(t,[["render",r]]);export{p as __pageData,_ as default};
